# Derive the predicted board from the stated geometry (0-based coordinates).
R, C = 19, 16
ones = {(2,2), (4,14), (10,10), (17,9)}
sixes = {(4,4), (6,6), (7,14), (15,2)}
# The only diagonal pair of 1s is (2,2)-(10,10): r-c=0, bounded segment.
main = {(r,r) for r in range(2,11)}
# 6s on that segment seed full perpendicular (slope -1) diagonals.
seed_sixes = sixes & main
six_lines = set()
for r0,c0 in seed_sixes:
    six_lines |= {(r,c) for r in range(R) for c in range(C) if r+c == r0+c0}
# Preserve the original 6 markers at intersections; fill new line cells as 6.
board = [[0]*C for _ in range(R)]
for r,c in ones: board[r][c] = 1
for r,c in sixes: board[r][c] = 6
for r,c in main: board[r][c] = 1
for r,c in six_lines: board[r][c] = 6
print('on-segment 6s:', sorted(seed_sixes))
print('off-segment 6s:', sorted(sixes-main))
print('1 segment:', sorted(main))
for s in sorted(seed_sixes):
    cells = sorted((r,c) for r,c in six_lines if r+c == sum(s))
    print(f'6 diagonal through {s}, r+c={sum(s)}: {cells[0]} .. {cells[-1]} ({len(cells)} cells)')
print('all nonzero predicted cells:')
for r,row in enumerate(board):
    cells = [(c,v) for c,v in enumerate(row) if v]
    if cells: print(r, cells)
print('compact grid:')
for row in board: print(' '.join(map(str,row)))
